import { createAudioPlayer, type AudioPlayer } from 'expo-audio';
import { useCallback } from 'react';
import { useStore } from '../store/AppStore';

/** Short UI sounds, generated by scripts/make-sounds.py. Practice only; mock tests stay silent like a real exam. */
const SOURCES = {
  correct: require('../../assets/sounds/correct.wav'),
  wrong: require('../../assets/sounds/wrong.wav'),
  complete: require('../../assets/sounds/complete.wav'),
} as const;
export type SoundName = keyof typeof SOURCES;

/** Quiet enough to sit under a student's music or a classroom. */
const VOLUME = 0.5;
const players: Partial<Record<SoundName, AudioPlayer>> = {};

function play(name: SoundName) {
  try {
    let p = players[name];
    if (!p) { p = createAudioPlayer(SOURCES[name]); p.volume = VOLUME; players[name] = p; }
    p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // Sound is a nice-to-have: never let it break practice.
  }
}

/** Returns a function that plays a sound unless the student turned sounds off in Settings. */
export function useSound() {
  const { data } = useStore();
  const on = data.settings.sounds !== false;
  return useCallback((name: SoundName) => { if (on) play(name); }, [on]);
}
